-- Schema for the online-shopping (food ordering) platform.
-- Derived from the MyBatis-Plus entities in com.taiwei.reggie.entity (the original project shipped no SQL).
--
-- Conventions
--  * ids are 64-bit snowflake ids generated by MyBatis-Plus (IdType.ASSIGN_ID)
--  * dish.price / setmeal.price / setmeal_dish.price are stored in the smallest currency unit (cents) because the
--    bundled UIs multiply by 100 on input and divide by 100 for display
--  * shopping_cart.amount, order_detail.amount and orders.amount are stored in currency units (e.g. 12.50)
--  * create_user / update_user are nullable so rows can also be written outside of an authenticated request

CREATE TABLE employee (
    id          BIGINT       NOT NULL PRIMARY KEY,
    name        VARCHAR(64)  NOT NULL,
    username    VARCHAR(64)  NOT NULL,
    password    VARCHAR(100) NOT NULL COMMENT 'BCrypt hash (legacy 32-char MD5 hashes are upgraded on first login)',
    phone       VARCHAR(20)  NOT NULL,
    sex         VARCHAR(2)   NOT NULL,
    id_number   VARCHAR(18)  NOT NULL,
    status      INT          NOT NULL DEFAULT 1 COMMENT '0 disabled, 1 enabled',
    create_time DATETIME     NOT NULL,
    update_time DATETIME     NOT NULL,
    create_user BIGINT       NULL,
    update_user BIGINT       NULL,
    UNIQUE KEY idx_employee_username (username)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'back-office staff';

CREATE TABLE category (
    id          BIGINT      NOT NULL PRIMARY KEY,
    type        INT         NULL COMMENT '1 dish category, 2 setmeal category',
    name        VARCHAR(64) NOT NULL,
    sort        INT         NOT NULL DEFAULT 0,
    create_time DATETIME    NOT NULL,
    update_time DATETIME    NOT NULL,
    create_user BIGINT      NULL,
    update_user BIGINT      NULL,
    UNIQUE KEY idx_category_name (name)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'dish / setmeal categories';

CREATE TABLE dish (
    id          BIGINT         NOT NULL PRIMARY KEY,
    name        VARCHAR(64)    NOT NULL,
    category_id BIGINT         NOT NULL,
    price       DECIMAL(10, 2) NULL COMMENT 'in cents',
    code        VARCHAR(64)    NULL,
    image       VARCHAR(200)   NULL,
    description VARCHAR(400)   NULL,
    status      INT            NOT NULL DEFAULT 1 COMMENT '0 stopped, 1 on sale',
    sort        INT            NOT NULL DEFAULT 0,
    create_time DATETIME       NOT NULL,
    update_time DATETIME       NOT NULL,
    create_user BIGINT         NULL,
    update_user BIGINT         NULL,
    is_deleted  INT            NOT NULL DEFAULT 0,
    UNIQUE KEY idx_dish_name (name),
    KEY idx_dish_category (category_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'dishes';

CREATE TABLE dish_flavor (
    id          BIGINT       NOT NULL PRIMARY KEY,
    dish_id     BIGINT       NOT NULL,
    name        VARCHAR(64)  NOT NULL,
    value       VARCHAR(500) NULL COMMENT 'JSON array of options, e.g. ["mild","hot"]',
    create_time DATETIME     NOT NULL,
    update_time DATETIME     NOT NULL,
    create_user BIGINT       NULL,
    update_user BIGINT       NULL,
    is_deleted  INT          NOT NULL DEFAULT 0,
    KEY idx_dish_flavor_dish (dish_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'flavour options of a dish';

CREATE TABLE setmeal (
    id          BIGINT         NOT NULL PRIMARY KEY,
    category_id BIGINT         NOT NULL,
    name        VARCHAR(64)    NOT NULL,
    price       DECIMAL(10, 2) NOT NULL COMMENT 'in cents',
    status      INT            NOT NULL DEFAULT 1 COMMENT '0 stopped, 1 on sale',
    code        VARCHAR(32)    NULL,
    description VARCHAR(512)   NULL,
    image       VARCHAR(255)   NULL,
    create_time DATETIME       NOT NULL,
    update_time DATETIME       NOT NULL,
    create_user BIGINT         NULL,
    update_user BIGINT         NULL,
    is_deleted  INT            NOT NULL DEFAULT 0,
    UNIQUE KEY idx_setmeal_name (name),
    KEY idx_setmeal_category (category_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'combo meals';

CREATE TABLE setmeal_dish (
    id          BIGINT         NOT NULL PRIMARY KEY,
    setmeal_id  BIGINT         NOT NULL,
    dish_id     BIGINT         NOT NULL,
    name        VARCHAR(64)    NULL COMMENT 'denormalised dish name',
    price       DECIMAL(10, 2) NULL COMMENT 'denormalised dish price, in cents',
    copies      INT            NOT NULL DEFAULT 1,
    sort        INT            NOT NULL DEFAULT 0,
    create_time DATETIME       NOT NULL,
    update_time DATETIME       NOT NULL,
    create_user BIGINT         NULL,
    update_user BIGINT         NULL,
    is_deleted  INT            NOT NULL DEFAULT 0,
    KEY idx_setmeal_dish_setmeal (setmeal_id),
    KEY idx_setmeal_dish_dish (dish_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'dishes contained in a combo meal';

CREATE TABLE `user` (
    id        BIGINT       NOT NULL PRIMARY KEY,
    name      VARCHAR(50)  NULL,
    phone     VARCHAR(100) NOT NULL COMMENT 'phone number (or email address when the email channel is used)',
    sex       VARCHAR(2)   NULL,
    id_number VARCHAR(18)  NULL,
    avatar    VARCHAR(500) NULL,
    status    INT          NOT NULL DEFAULT 1 COMMENT '0 disabled, 1 normal',
    UNIQUE KEY idx_user_phone (phone)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'customers';

CREATE TABLE address_book (
    id            BIGINT       NOT NULL PRIMARY KEY,
    user_id       BIGINT       NOT NULL,
    consignee     VARCHAR(50)  NOT NULL,
    sex           VARCHAR(2)   NULL,
    phone         VARCHAR(50)  NOT NULL,
    province_code VARCHAR(12)  NULL,
    province_name VARCHAR(32)  NULL,
    city_code     VARCHAR(12)  NULL,
    city_name     VARCHAR(32)  NULL,
    district_code VARCHAR(12)  NULL,
    district_name VARCHAR(32)  NULL,
    detail        VARCHAR(200) NULL,
    label         VARCHAR(100) NULL,
    is_default    INT          NOT NULL DEFAULT 0,
    create_time   DATETIME     NOT NULL,
    update_time   DATETIME     NOT NULL,
    create_user   BIGINT       NULL,
    update_user   BIGINT       NULL,
    is_deleted    INT          NOT NULL DEFAULT 0,
    KEY idx_address_user (user_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'delivery addresses';

CREATE TABLE shopping_cart (
    id          BIGINT         NOT NULL PRIMARY KEY,
    name        VARCHAR(64)    NULL,
    image       VARCHAR(200)   NULL,
    user_id     BIGINT         NOT NULL,
    dish_id     BIGINT         NULL,
    setmeal_id  BIGINT         NULL,
    dish_flavor VARCHAR(50)    NULL,
    number      INT            NOT NULL DEFAULT 1,
    amount      DECIMAL(10, 2) NOT NULL COMMENT 'unit price in currency units',
    create_time DATETIME       NULL,
    KEY idx_cart_user (user_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'shopping cart rows';

CREATE TABLE orders (
    id               BIGINT         NOT NULL PRIMARY KEY,
    number           VARCHAR(50)    NULL,
    status           INT            NOT NULL DEFAULT 1 COMMENT '1 awaiting payment, 2 awaiting dispatch, 3 dispatched, 4 completed, 5 cancelled',
    user_id          BIGINT         NOT NULL,
    address_book_id  BIGINT         NOT NULL,
    order_time       DATETIME       NOT NULL,
    checkout_time    DATETIME       NULL,
    pay_method       INT            NOT NULL DEFAULT 1 COMMENT '1 WeChat, 2 Alipay',
    amount           DECIMAL(10, 2) NOT NULL COMMENT 'total in currency units',
    remark           VARCHAR(100)   NULL,
    phone            VARCHAR(255)   NULL,
    address          VARCHAR(255)   NULL,
    user_name        VARCHAR(255)   NULL,
    consignee        VARCHAR(255)   NULL,
    UNIQUE KEY idx_orders_number (number),
    KEY idx_orders_user_time (user_id, order_time),
    KEY idx_orders_time (order_time)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'orders';

CREATE TABLE order_detail (
    id          BIGINT         NOT NULL PRIMARY KEY,
    name        VARCHAR(64)    NULL,
    image       VARCHAR(200)   NULL,
    order_id    BIGINT         NOT NULL,
    dish_id     BIGINT         NULL,
    setmeal_id  BIGINT         NULL,
    dish_flavor VARCHAR(50)    NULL,
    number      INT            NOT NULL DEFAULT 1,
    amount      DECIMAL(10, 2) NOT NULL COMMENT 'unit price in currency units',
    KEY idx_order_detail_order (order_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'order line items';
